<?php
$plans=db()->query('SELECT * FROM plans ORDER BY active DESC,duration_days')->fetchAll();
$clients=db()->query('SELECT id,name FROM clients WHERE active=1 ORDER BY name')->fetchAll();
$rows=db()->query('SELECT m.*,c.name client_name,p.name plan_name,p.price FROM memberships m JOIN clients c ON c.id=m.client_id JOIN plans p ON p.id=m.plan_id ORDER BY m.id DESC LIMIT 100')->fetchAll();
?>
<?php if(is_admin()): ?><div class="actions" style="justify-content:flex-end;margin-bottom:12px"><button class="btn" onclick="document.getElementById('plan-form').classList.toggle('hidden')">＋ Nuevo plan</button></div><section class="card panel hidden" id="plan-form"><div class="panel-head"><h2 id="plan-form-title">Crear plan</h2></div><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="plan_save"><input type="hidden" name="id" value=""><label>Nombre<input name="name" required></label><label>Precio (Bs)<input name="price" type="number" min="0" step="0.01" required></label><label>Duración (días)<input name="duration_days" type="number" min="1" required></label><label style="grid-column:1/-1">Descripción<input name="description"></label><div class="form-actions"><button class="btn primary">Guardar plan</button></div></form></section><?php endif; ?>
<section class="card panel hidden" id="membership-form"><div class="panel-head"><h2>Crear membresía y registrar el pago</h2></div><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="membership_create"><label>Cliente<select name="client_id" required><option value="">Seleccionar cliente</option><?php foreach($clients as $c): ?><option value="<?=$c['id']?>"><?=h($c['name'])?></option><?php endforeach; ?></select></label><label>Plan<select name="plan_id" required><option value="">Seleccionar plan</option><?php foreach($plans as $p): if($p['active']): ?><option value="<?=$p['id']?>"><?=h($p['name'])?> · <?=money($p['price'])?> · <?=$p['duration_days']?> días</option><?php endif; endforeach; ?></select></label><label>Inicio<input name="start_date" type="date" value="<?=date('Y-m-d')?>" required></label><div class="form-actions"><button class="btn primary">Crear y registrar pago inicial</button></div></form></section>
<div class="grid stats"><?php foreach($plans as $p): ?><article class="card stat"><div class="stat-top"><span><?=h($p['name'])?></span><span class="stat-icon">◉</span></div><div class="stat-value" style="font-size:20px"><?=money($p['price'])?></div><div class="stat-foot"><?=$p['duration_days']?> días · <?=h($p['active']?'Disponible':'Inactivo')?></div><?php if(is_admin()): ?><div class="actions" style="margin-top:8px"><button class="link-btn" data-edit-plan='<?=h(json_encode(['id'=>$p['id'],'name'=>$p['name'],'price'=>$p['price'],'duration_days'=>$p['duration_days'],'description'=>$p['description']],JSON_HEX_APOS|JSON_HEX_QUOT|JSON_HEX_TAG|JSON_HEX_AMP))?>'>Editar</button><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="plan_toggle"><input type="hidden" name="id" value="<?=$p['id']?>"><button class="link-btn"><?=$p['active']?'Desactivar':'Activar'?></button></form></div><?php endif; ?></article><?php endforeach; ?></div><div class="alert">Los tres planes y precios iniciales son datos de demostración. Administración puede reemplazarlos por las tarifas vigentes del gimnasio.</div>
<section class="card panel"><div class="panel-head"><h2>Historial de membresías</h2><input class="search" data-search="#membership-table" placeholder="Buscar cliente o plan…"></div><div class="table-wrap"><table id="membership-table"><thead><tr><th>CLIENTE</th><th>PLAN</th><th>INICIO</th><th>VENCIMIENTO</th><th>PRECIO</th><th>ESTADO</th></tr></thead><tbody><?php foreach($rows as $r): $valid=$r['status']==='active'&&$r['end_date']>=date('Y-m-d');$status=$valid?'Activa':($r['end_date']<date('Y-m-d')?'Vencida':ucfirst($r['status'])); ?><tr><td><?=h($r['client_name'])?></td><td><?=h($r['plan_name'])?></td><td><?=date('d/m/Y',strtotime($r['start_date']))?></td><td><?=date('d/m/Y',strtotime($r['end_date']))?></td><td><?=money($r['price'])?></td><td><span class="pill <?=$valid?'':'expired'?>"><?=h($status)?></span></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="6" class="empty">Aún no hay membresías creadas.</td></tr><?php endif; ?></tbody></table></div></section>
